function metricBox(label,value,cls=''){return`<div class="v372-strip-item ${cls}"><span>${esc(label)}</span><b>${esc(value)}</b></div>`}
function stripHtml(r,ctx){const v=r.video||{},tax=sourceTaxonomy(r),m=baseline(ctx,r),o=outlier(ctx,r),subs=subscriberFrom(ctx,r),retrieved=r.retrieved_at||new Date().toISOString();window.__YTINTEL_VIDEO_TAXONOMY={...tax,basis:'Source-only title, description, tags and transcript. Creator DNA excluded.'};return`<div class="v372-strip-grid">${metricBox('Title',v.title||'—','wide')}${metricBox('Channel',v.channel||'—')}${metricBox('Subscribers',compact(subs))}${metricBox('Views',compact(v.view_count))}${metricBox('Likes',v.like_count==null?'—':nfmt(v.like_count))}${metricBox('Comments',v.comment_count==null?'—':nfmt(v.comment_count))}${metricBox('Upload',v.upload_date?new Date(dateMs(v.upload_date)).toLocaleDateString():'—')}${metricBox('Age',ageText(v.upload_date))}${metricBox('Length',fmt(v.duration))}${metricBox('Channel median',compact(m))}${metricBox('Outlier',o?`${o.toFixed(2)}×`:'—')}${metricBox('Niche',tax.niche)}${metricBox('Subniche',tax.subniche,'wide')}</div><div class="v372-source-note">Pulled ${esc(new Date(retrieved).toLocaleString())}. Niche and subniche describe this source video only; Creator DNA cannot leak into this strip. Missing analytics render as —, never fake zeroes.</div>`}
function first(rows,rx,min=0){return rows.find(x=>x.time>=min&&rx.test(x.text))||null}
function keyProofs(r){const rows=sentenceRows(r),title=r?.video?.title||'';return [...rows].filter(x=>rowType(x.text)!=='CTA / funnel').sort((a,b)=>rowScore(b,title)-rowScore(a,title))}
function summaryHtml(r,ctx){const v=r.video||{},rows=sentenceRows(r),e=evidenceRows(r,10),opening=rows[0],proof=keyProofs(r).find(x=>/proof|receipt|number|demonstration|example/i.test(rowType(x.text)))||e[1],conclusion=first(rows,/\b(result|turns out|therefore|this means|the point is|what happens|here'?s what happened|the reason)\b/i,15)||e[Math.floor(e.length*.65)],objection=first(rows,/\b(but|however|misconception|problem|catch|risk|doesn'?t|won'?t)\b/i,20),cta=first(rows,/\b(work with me|book|join|discord|subscribe|link below|software|course|apply|buy)\b/i,20),m=baseline(ctx,r),o=outlier(ctx,r),sellRows=rows.filter(x=>rowType(x.text)==='CTA / funnel'),titleSurface=titleSurfaces(r,ctx).unique.length,replay=!!r?.heatmap?.available,p=profile();const chain=e.slice(0,9).map(x=>`${fmt(x.time)} ${clip(x.text,92)}`).join(' → ');const argument=[proof,conclusion,objection].filter(Boolean).filter((x,i,a)=>a.findIndex(y=>y?.text===x.text)===i).slice(0,3);const take=sourceMechanics(r,7).slice(0,5).map(x=>x.name.toLowerCase()).join(', ');return`<div class="v372-kicker">Watch replacement. Concrete source content first; no generic “main message” model sentence and no Opening / Development transcript buckets in this section.</div><div class="v372-summary"><article><b>What the video is</b><p>“${esc(v.title||'This video')}” is a ${esc(fmt(v.duration))} upload from ${esc(v.channel||'the source channel')}. It opens with “${esc(clip(opening?.text||'No opening caption was available.',210))}”${proof?` and supports the idea with “${esc(clip(proof.text,190))}”`:''}.${cta?` The video later moves into an explicit commercial/community action around ${esc(fmt(cta.time))}: “${esc(clip(cta.text,150))}”.`:''} The actual subject is ${esc(terms(`${v.title} ${rows.slice(0,20).map(x=>x.text).join(' ')}`,7).join(', ')||'the source topic')}.</p></article><article><b>How it is built</b><p class="v372-chain">${esc(chain||'The transcript did not expose enough timed evidence for a reliable build chain.')}${sellRows.length?` → ${sellRows.length} direct CTA/funnel cue${sellRows.length===1?'':'s'} detected`:''}.</p></article><article><b>How it is doing</b><p>${esc(compact(v.view_count))} views at ${esc(ageText(v.upload_date))} old${m?` against a positive channel median of ${esc(compact(m))}`:''}${o?` (${o.toFixed(2)}×)`:''}. ${v.like_count==null?'Likes unavailable.':`${nfmt(v.like_count)} likes.`} ${v.comment_count==null?'Comments unavailable.':`${nfmt(v.comment_count)} comments.`} ${replay?'A public Most Replayed curve is exposed and Section 7 uses it.':'No public Most Replayed curve is exposed on this pull, so Section 7 uses clearly labelled transcript hypotheses instead.'} ${titleSurface>1?`${titleSurface} distinct public title surfaces were observed; that is title-variation evidence, not automatic proof of a Studio A/B test.`:'Only one reliable title surface is available.'}</p></article><article><b>What the argument actually comes down to</b><p>${argument.length?argument.map(x=>`${fmt(x.time)}: “${clip(x.text,185)}”`).map(esc).join(' ') : 'The transcript does not contain a clean result statement, so YTIntel is not inventing one.'} ${conclusion?`The strongest conclusion cue lands around ${esc(fmt(conclusion.time))}.`:''}</p></article><article><b>What is worth taking${p.niche?` for ${esc(p.channel||p.niche)}`:''}</b><p>${esc(take||'the source’s promise, proof timing, examples, objection handling and payoff placement')}. These are source mechanics only. Section 14 turns them into an original blueprint for ${esc(p.subniche||p.niche||'your channel')} and applies your brand rules.</p></article></div>`}
function takeawayInstruction(x,r){const type=rowType(x.text),k=terms(x.text,3).join(', ')||terms(r?.video?.title||'',3).join(', ')||'the point';if(type==='Promise / hook')return`State the concrete promise around ${k} immediately, then make the rest of the video earn it.`;if(type==='Number / receipt'||type==='Demonstration / proof')return`Move a checkable receipt, number or demonstration for ${k} close to the claim instead of asking for blind trust.`;if(type==='Example / case study')return`Use a named example around ${k} to turn the argument into something the viewer can inspect.`;if(type==='Mechanism')return`Explain why ${k} works, not only the outcome. The mechanism is what makes the idea transferable.`;if(type==='Objection / correction')return`Pre-empt the obvious objection around ${k}; the correction doubles as an attention reset.`;if(type==='Payoff / conclusion')return`Land the conclusion around ${k} as a distinct payoff rather than letting it disappear inside explanation.`;if(type==='CTA / funnel')return`Separate the value delivery from the CTA around ${k} so the sell does not masquerade as proof.`;return`Turn the point about ${k} into a specific example, decision or next action instead of leaving it as filler.`}
function takeawaysHtml(r){const rows=sentenceRows(r),title=r?.video?.title||'',scored=[...rows].sort((a,b)=>rowScore(b,title)-rowScore(a,title)),picked=spacedPick(scored,8,Math.max(16,(Number(r?.video?.duration)||300)/18));if(picked.length<5&&rows.length){const step=Math.max(1,Math.floor(rows.length/7));for(let i=0;i<rows.length&&picked.length<7;i+=step){const x=rows[i];if(picked.every(y=>Math.abs(y.time-x.time)>10&&overlap(y.text,x.text)<.72))picked.push(x)}}picked.sort((a,b)=>a.time-b.time);return`<div class="v372-kicker">${picked.length} source-backed takeaways. Every item has an action, timestamp and receipt; a valid transcript will never be replaced by “takeaways could not be separated.”</div><div class="v372-full-list">${picked.slice(0,8).map((x,i)=>`<div class="v372-evidence-card"><span class="t">${i+1} · ${fmt(x.time)}</span><div><b>${esc(takeawayInstruction(x,r))}</b><blockquote>“${esc(clip(x.text,250))}”</blockquote></div></div>`).join('')||'<div class="v372-muted">No transcript was returned by the source, so takeaways cannot be evidenced.</div>'}</div>`}
function hookHtml(r){const rows=sentenceRows(r).filter(x=>x.time<60).slice(0,22),promise=first(rows,/\b(i(?:'m| am) going to|i will|you will|we will|in this video|here'?s how|show you|prove it|today)\b/i),receipt=first(rows,/\b(dashboard|revenue|earned|made|generated|proof|receipt|you can see|show you)\b|\$\s?\d/i),type=clean(r?.hook_framework?.primary_type||r?.hook_story?.hook?.type||rowType(rows[0]?.text));return`<div class="v372-metrics"><div class="v372-metric"><span>Hook type</span><b>${esc(type||'source-defined')}</b></div><div class="v372-metric"><span>First promise</span><b>${promise?fmt(promise.time):'—'}</b></div><div class="v372-metric"><span>First proof cue</span><b>${receipt?fmt(receipt.time):'—'}</b></div><div class="v372-metric"><span>Opening lines</span><b>${rows.length}</b></div></div><div class="v372-full-list">${rows.map(x=>`<div class="v372-evidence-card"><span class="t">${fmt(x.time)}</span><div><b>${esc(rowType(x.text))}</b><p>${esc(takeawayInstruction(x,r))}</p><blockquote>“${esc(clip(x.text,300))}”</blockquote></div></div>`).join('')}</div>`}
function resetReason(x,prev){const s=x.text.toLowerCase();if(/\b(but|however|no,|doesn'?t mean|misconception|problem|catch|instead)\b/.test(s))return'Contrast / correction resets the viewer’s interpretation.';if(/\?/.test(x.text)||/^(?:why|how|what|would|can|do)\b/.test(s))return'A question opens a fresh information gap.';if(/\b(show you|look at|take a look|dashboard|proof|you can see)\b/.test(s))return'Switches from telling to proof or demonstration.';if(/\b(for example|another|next|second|third|case study)\b/.test(s))return'Introduces a new example or chapter.';if(rowType(x.text)==='CTA / funnel')return'Changes mode from content into an action / funnel beat.';if(prev&&overlap(prev.text,x.text)<.12)return'Topic language changes sharply, creating a new attention target.';return'New claim or section boundary refreshes the attention target.'}
function rehookRows(r){const rows=sentenceRows(r),cand=[];let prev=null,last=-999;for(const x of rows){if(x.time<12){prev=x;continue}const s=x.text.toLowerCase();let score=0;if(/^(?:but|however|now|next|another|actually|instead|so here|the problem|the thing|here'?s|let me|what|why|how)\b/.test(s))score+=4;if(/[?]/.test(x.text))score+=3;if(/\b(show you|look at|take a look|proof|dashboard|for example|misconception|catch|problem)\b/.test(s))score+=3;if(prev&&rowType(prev.text)!==rowType(x.text)&&rowType(x.text)!=='Development')score+=2;if(prev&&overlap(prev.text,x.text)<.12)score+=1;if(score>=3&&x.time-last>=10){cand.push({...x,reason:resetReason(x,prev),score});last=x.time}prev=x}if(cand.length<5){for(const x of evidenceRows(r,12)){if(x.time>12&&cand.every(y=>Math.abs(y.time-x.time)>12)){cand.push({...x,reason:resetReason(x,null),score:2});if(cand.length>=7)break}}}return cand.sort((a,b)=>a.time-b.time).slice(0,18)}
function rehooksHtml(r){const rows=rehookRows(r),gaps=rows.slice(1).map((x,i)=>x.time-rows[i].time).filter(x=>x>0),med=median(gaps);return`<div class="v372-metrics"><div class="v372-metric"><span>Attention resets</span><b>${rows.length||'—'}</b></div><div class="v372-metric"><span>Median spacing</span><b>${med?`${Math.round(med)}s`:'—'}</b></div><div class="v372-metric"><span>First re-hook</span><b>${rows[0]?fmt(rows[0].time):'—'}</b></div><div class="v372-metric"><span>Method</span><b>Transcript + topic shift</b></div></div><div class="v372-full-list">${rows.map((x,i)=>`<div class="v372-evidence-card"><span class="t">${i+1} · ${fmt(x.time)}</span><div><b>${esc(x.reason)}</b><blockquote>“${esc(clip(x.text,280))}”</blockquote></div></div>`).join('')||'<div class="v372-muted">No defensible re-hook candidates were found in the available transcript.</div>'}</div>`}
function payoffRows(r){const title=r?.video?.title||'',rows=sentenceRows(r),out=[];for(const x of rows){if(x.time<12)continue;const type=rowType(x.text),s=x.text.toLowerCase();let score=0;if(type==='Payoff / conclusion')score+=6;if(type==='Demonstration / proof'||type==='Number / receipt')score+=5;if(/\b(result|answer|therefore|this means|what happens|you can see|proof|made|earned|generated|works)\b/.test(s))score+=3;score+=Math.round(overlap(x.text,title)*3);if(score>=6&&out.every(y=>Math.abs(y.time-x.time)>14&&overlap(y.text,x.text)<.68))out.push({...x,score});if(out.length>=14)break}return out}
function promiseDelivery(r){const ts=terms(r?.video?.title||'',8);if(!ts.length)return{score:null,label:'Unclear'};const dur=Number(r?.video?.duration)||0,body=sentenceRows(r).filter(x=>x.time>Math.min(45,dur*.12)).map(x=>x.text.toLowerCase()).join(' '),hit=ts.filter(x=>body.includes(x)).length/ts.length;return{score:hit,label:hit>=.65?'Delivered':hit>=.35?'Partially delivered':'Weak / unclear'}}
function payoffsHtml(r){const rows=payoffRows(r),dur=Math.max(1,Number(r?.video?.duration)||1),pd=promiseDelivery(r),ppm=rows.length/(dur/60);return`<div class="v372-metrics"><div class="v372-metric"><span>First payoff</span><b>${rows[0]?fmt(rows[0].time):'—'}</b></div><div class="v372-metric"><span>Payoffs / min</span><b>${rows.length?ppm.toFixed(2):'—'}</b></div><div class="v372-metric"><span>Title promise</span><b>${esc(pd.label)}</b></div><div class="v372-metric"><span>Tracked payoffs</span><b>${rows.length||'—'}</b></div></div><div class="v372-full-list">${rows.map((x,i)=>`<div class="v372-evidence-card"><span class="t">${i+1} · ${fmt(x.time)}</span><div><b>${esc(rowType(x.text))}: this is where a claim gets evidence, a result or a conclusion.</b><blockquote>“${esc(clip(x.text,280))}”</blockquote></div></div>`).join('')||'<div class="v372-muted">No strong source-backed payoff sentence was detected. YTIntel is not treating the opening promise itself as a payoff.</div>'}</div>`}
function heatTroughs(r){const xs=r?.heatmap?.normalized_100||[],out=[];for(let i=1;i<xs.length-1;i++){const v=Number(xs[i].value);if(Number.isFinite(v)&&v<=Number(xs[i-1].value)&&v<=Number(xs[i+1].value))out.push({...xs[i],index:i})}return out.sort((a,b)=>Number(a.value)-Number(b.value)).slice(0,5)}
function nearestSemantic(r,time){const d=deepEntry(r?.video?.id),xs=d?.visual?.semantic_frames||[];return [...xs].sort((a,b)=>Math.abs(Number(a.time)-time)-Math.abs(Number(b.time)-time))[0]||null}
function screenRead(r,time){const x=nearestSemantic(r,time)?.analysis;if(!x)return'On-screen state is not reliably classified on this device; check the nearest inspected frame in Section 9.';return clean([x.production_mode,x.role,x.composition,x.notes].filter(Boolean).join(' · '))||'Semantic frame exists but no reliable description was returned.'}
function replayHtml(r){const h=r?.heatmap||{};if(h.available){const peaks=(h.top_peaks||[]).slice(0,6),tr=heatTroughs(r);return`<div class="v372-kicker">Real public Most Replayed data is available. Peaks are replay / seek-interest evidence, not private Studio retention.</div><h3>Peaks</h3><div class="v372-full-list">${peaks.map(x=>{const q=quoteAt(r,Number(x.time));return`<div class="v372-evidence-card"><span class="t">${fmt(x.time)}</span><div><b>Replay peak · ${Number(x.value||0).toFixed(3)}</b>${q?`<blockquote>“${esc(clip(q.text,260))}”</blockquote>`:''}<p><b>On screen:</b> ${esc(screenRead(r,Number(x.time)))}</p></div></div>`}).join('')}</div><h3 style="margin-top:15px">Troughs</h3><div class="v372-full-list">${tr.map(x=>{const q=quoteAt(r,Number(x.time));return`<div class="v372-evidence-card"><span class="t">${fmt(x.time)}</span><div><b>Replay trough · ${Number(x.value||0).toFixed(3)}</b>${q?`<blockquote>“${esc(clip(q.text,240))}”</blockquote>`:''}<p><b>On screen:</b> ${esc(screenRead(r,Number(x.time)))}</p></div></div>`}).join('')}</div>`}const hyp=[...payoffRows(r),...rehookRows(r)].sort((a,b)=>b.score-a.score).filter((x,i,a)=>a.slice(0,i).every(y=>Math.abs(y.time-x.time)>22)).slice(0,6).sort((a,b)=>a.time-b.time);return`<div class="v372-kicker" style="border-color:#5b4520;background:#17130a;color:#e6cb86">No public Most Replayed curve was exposed. The items below are HYPOTHESES only, exactly as the Monday brief requires when replay data is unavailable.</div><div class="v372-full-list">${hyp.map(x=>`<div class="v372-evidence-card v372-hypothesis"><span class="t">HYP · ${fmt(x.time)}</span><div><b>${esc(/proof|receipt|payoff/i.test(rowType(x.text))?'A concrete proof / payoff moment may invite rewatching.':'A strong attention reset may be a replay candidate.')}</b><blockquote>“${esc(clip(x.text,270))}”</blockquote><p>This is inferred from transcript structure only. It is not labelled as replay or retention data.</p></div></div>`).join('')||'<div class="v372-muted">The source did not expose enough timed transcript evidence to form useful replay hypotheses.</div>'}</div>`}
function mechanicName(x){const t=rowType(x.text);if(t==='Promise / hook')return'Open with a promise that creates a debt';if(t==='Number / receipt'||t==='Demonstration / proof')return'Put proof before explanation';if(t==='Example / case study')return'Use a named example with inspectable evidence';if(t==='Mechanism')return'Give the claim a physical or logical mechanism';if(t==='Objection / correction')return'Correct the viewer’s first interpretation';if(t==='Payoff / conclusion')return'Turn evidence into a clean payoff';if(t==='CTA / funnel')return'Separate the funnel from the proof';return'Advance with a concrete new beat'}
function sourceMechanics(r,count=8){const rows=evidenceRows(r,14),out=[];for(const x of rows){const name=mechanicName(x);if(out.some(y=>y.name===name))continue;out.push({name,row:x,why:takeawayInstruction(x,r)});if(out.length>=count)break}return out}
function structureBeats(r,count=10){const rows=sentenceRows(r),dur=Math.max(Number(r?.video?.duration)||rows.at(-1)?.time||1,1),out=[];for(let i=0;i<count;i++){const a=dur*i/count,b=dur*(i+1)/count,within=rows.filter(x=>x.time>=a&&x.time<b);if(!within.length)continue;const x=[...within].sort((u,v)=>rowScore(v,r?.video?.title||'')-rowScore(u,r?.video?.title||''))[0];out.push({a,b,row:x,type:rowType(x.text)})}return out}
function mechanicsHtml(r){const ms=sourceMechanics(r,9),beats=structureBeats(r,10);return`<div class="v372-kicker">SOURCE ONLY. This section answers “what mechanics are worth stealing from their video?” Section 14 is different: it converts these mechanics into your niche, your channel, your proof and your brand rules.</div><div class="v372-mechanics">${ms.map((m,i)=>`<div class="v372-mechanic"><strong>${i+1}</strong><div><h3>${esc(m.name)}</h3><p>${esc(m.why)}</p><p><b>${fmt(m.row.time)}</b> · “${esc(clip(m.row.text,230))}”</p></div></div>`).join('')}</div><h3 style="margin:18px 0 7px">Source structure map</h3><div class="v372-structure">${beats.map(b=>`<div class="v372-beat"><span>${fmt(b.a)}–${fmt(b.b)}</span><b>${esc(b.type)}</b><p>“${esc(clip(b.row.text,190))}”</p><p>${esc(screenRead(r,b.row.time))}</p></div>`).join('')}</div>`}
